<?php $interests = function_exists( 'sd_core_available_interests' ) ? sd_core_available_interests() : array(); $selected = function_exists( 'sd_core_user_interests' ) ? sd_core_user_interests( get_current_user_id() ) : array(); ?><div class="sd-onboarding-step"><span class="sd-eyebrow"><?php esc_html_e( 'Step 4 of 6', 'social-discovery' ); ?></span><h2><?php esc_html_e( 'Choose a few interests', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'Select only what you are comfortable sharing. You can change this later.', 'social-discovery' ); ?></p><?php if ( $interests ) : ?><div class="sd-interest-selector"><?php foreach ( $interests as $interest ) : ?><label><input type="checkbox" name="interests[]" value="<?php echo esc_attr( $interest ); ?>" <?php checked( in_array( $interest, $selected, true ) ); ?>><span><?php echo esc_html( $interest ); ?></span></label><?php endforeach; ?></div><?php else : ?><p class="sd-field-help"><?php esc_html_e( 'No public interests have been configured yet.', 'social-discovery' ); ?></p><?php endif; ?></div>
